/* Card set: RollerCoaster Tycoon (generated from the approved roster-v2.csv by the RCT build).
   Squat icon cards: see css/rct.css for the v3 layout (square art zone, text strip below). */
CardSets.register({"id":"rct","name":"RollerCoaster Tycoon","code":"RCT","description":"171 cards from the isometric park - every coaster and flat ride, the trains, boats and burger stalls that keep the guests smiling, and 17 classic scenarios, from Forest Frontiers and the Giga Coaster to the legendary Toilets.","theme":{"primary":"#2e6b30","secondary":"#e07b2a","artBackground":"#17251a","artFit":"cover"},"pack":{"name":"RollerCoaster Tycoon Pack","emblem":"🎢","skin":"rct","slots":[{"count":3,"label":"Common","odds":{"common":100}},{"count":1,"label":"Uncommon","odds":{"uncommon":100}},{"count":1,"label":"Wild card","odds":{"common":55,"uncommon":30,"rare":12,"epic":3}},{"count":1,"label":"Rare or better (guaranteed)","odds":{"rare":81.8,"epic":14,"legendary":4,"chase":0.2}}]},"cards":[{"name":"Forest Frontiers","rarity":"chase","id":"forest-frontiers","subtitle":"Scenario","details":"Deep in the forest, a large clearing waits for its first rides. Build a thriving little park from scratch and learn the ropes in this gentle opener.","image":"https://vignette.wikia.nocookie.net/rct/images/b/be/Forest_Frontiers_RCT1.png/revision/latest?cb=20151114185910"},{"name":"Rainbow Valley","rarity":"chase","id":"rainbow-valley","subtitle":"Scenario","details":"A long, hilly river valley thick with protected trees, where no land can be reshaped. Squeeze a large theme park in anyway, building around nature.","image":"https://vignette.wikia.nocookie.net/rct/images/6/6c/Rainbow_Valley_RCT1.png/revision/latest?cb=20151114221159"},{"name":"Bumbly Beach","rarity":"legendary","id":"bumbly-beach","subtitle":"Scenario","details":"A small seaside amusement park sits by the beach, rides already humming. Grow it into a thriving theme park without losing its breezy charm.","image":"https://vignette.wikia.nocookie.net/rct/images/a/ad/Bumbly_Beach_RCT1.png/revision/latest?cb=20151114214902"},{"name":"Diamond Heights","rarity":"legendary","id":"diamond-heights","subtitle":"Scenario","details":"Already a successful park among forest and lake, with great rides in place. Develop it carefully and double its value to prove it can shine brighter.","image":"https://vignette.wikia.nocookie.net/rct/images/5/5f/Diamond_Heights_RCT1.png/revision/latest?cb=20151114185911"},{"name":"Megaworld Park","rarity":"legendary","id":"megaworld-park","subtitle":"Scenario","details":"A giant park packed with rides yet falling apart, short on shops and tidy paths. Rescue it from ruin and turn its crowds into a thriving success.","image":"https://vignette.wikia.nocookie.net/rct/images/d/d7/Megaworld_Park_RCT1.png/revision/latest?cb=20151115120631"},{"name":"Arid Heights","rarity":"epic","id":"arid-heights","subtitle":"Scenario","details":"A vast desert park with no money worries at all. Your only challenge is keeping guests happy while you build freely under the hot sun.","image":"https://vignette.wikia.nocookie.net/rct/images/2/2d/Arid_Heights_RCT1.png/revision/latest?cb=20151115115604"},{"name":"Evergreen Gardens","rarity":"epic","id":"evergreen-gardens","subtitle":"Scenario","details":"Beautiful formal gardens that were never meant for coasters. Convert them into a thriving theme park, fitting rides among the trees and flowerbeds.","image":"https://vignette.wikia.nocookie.net/rct/images/a/ac/Evergreen_Gardens_RCT1.png/revision/latest?cb=20151114185911"},{"name":"Leafy Lake","rarity":"epic","id":"leafy-lake","subtitle":"Scenario","details":"Starting from scratch beside a large, leafy lake, with hills beyond. Build a theme park around the water and make the scenic site bustle.","image":"https://vignette.wikia.nocookie.net/rct/images/2/26/Leafy_Lake_RCT1.png/revision/latest?cb=20151114185910"},{"name":"Dynamite Dunes","rarity":"rare","id":"dynamite-dunes","subtitle":"Scenario","details":"Out in the desert dunes, one lone coaster already dives underground. Expand around it and build a busy park in the sand and heat.","image":"https://vignette.wikia.nocookie.net/rct/images/b/bd/Dynamite_Dunes_RCT1.png/revision/latest?cb=20151114185910"},{"name":"Fiasco Forest","rarity":"rare","id":"fiasco-forest","subtitle":"Scenario","details":"A forest park full of badly designed, dangerous rides and very little time or money. Fix the mess and turn this fiasco around.","image":"https://vignette.wikia.nocookie.net/rct/images/4/45/Fiasco_Forest_RCT1.png/revision/latest?cb=20151114231141"},{"name":"Thunder Rock","rarity":"rare","id":"thunder-rock","subtitle":"Scenario","details":"A huge rock rises from the desert, served by a chairlift to its summit. Build rides around and under it to draw even more tourists in.","image":"https://vignette.wikia.nocookie.net/rct/images/b/b4/Thunder_Rock_RCT1.png/revision/latest?cb=20151114221214"},{"name":"Amity Airfield","rarity":"uncommon","id":"amity-airfield","subtitle":"Scenario","details":"An abandoned airport with its runway and control tower still standing. Build a flying-themed park on the flat ground and fill the skies with fun.","image":"https://vignette.wikia.nocookie.net/rct/images/5/56/Amity_Airfield_RCT2.png/revision/latest/scale-to-width-down/1024?cb=20150725153409"},{"name":"Gravity Gardens","rarity":"uncommon","id":"gravity-gardens","subtitle":"Scenario","details":"Beautiful gardens where only roller coasters are allowed, no other rides at all. Build a coaster-only park valuable enough to clear its debts.","image":"https://vignette.wikia.nocookie.net/rct/images/0/0d/Gravity_Gardens.PNG/revision/latest?cb=20100118214433"},{"name":"Micro Park","rarity":"uncommon","id":"micro-park","subtitle":"Scenario","details":"The world's smallest park plot, just a tiny patch of grass. Squeeze in enough rides and charm to make this miniature park profitable.","image":"https://vignette.wikia.nocookie.net/rct/images/1/1f/Micro_Park_RCT1.png/revision/latest?cb=20151115120624"},{"name":"Crazy Castle","rarity":"common","id":"crazy-castle","subtitle":"Scenario","details":"You have inherited a large, empty castle fit for a fairy tale. Convert its halls and grounds into a small theme park guests will love.","image":"https://vignette.wikia.nocookie.net/rct/images/7/78/Crazy_Castle_RCT2.png/revision/latest?cb=20151128103113"},{"name":"Electric Fields","rarity":"common","id":"electric-fields","subtitle":"Scenario","details":"You have inherited a small farm, fields and barns included. Build a cosy little theme park among them, around its trees and small lake.","image":"https://vignette.wikia.nocookie.net/rct/images/b/b1/Electric_Fields_RCT2.png/revision/latest?cb=20151128103315"},{"name":"Rainbow Summit","rarity":"common","id":"rainbow-summit","subtitle":"Scenario","details":"A hillside park where nothing may rise above the treetops. Expand it low and clever, and make it a success without ever building tall.","image":"https://vignette.wikia.nocookie.net/rct/images/3/32/Rainbow_Summit.png/revision/latest?cb=20100124164130"},{"name":"Giga Coaster","rarity":"chase","id":"giga-coaster","subtitle":"Roller Coaster","details":"A steel giant built for sheer scale, stacking huge drops, long airtime hills and blistering speed into the kind of ride guests queue for hours to conquer.","image":"https://vignette.wikia.nocookie.net/rct/images/0/05/Giga_Coaster_RCT2_Icon.png/revision/latest?cb=20150725164908"},{"name":"Inverted Roller Coaster","rarity":"chase","id":"inverted-roller-coaster","subtitle":"Roller Coaster","details":"Trains hang beneath the track with riders' feet dangling free, flipping through loops and rolls with nothing below but air and the path rushing past.","image":"https://vignette.wikia.nocookie.net/rct/images/e/ed/4-Across_Inverted_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725165328"},{"name":"Looping Roller Coaster","rarity":"chase","id":"looping-roller-coaster","subtitle":"Roller Coaster","details":"The classic steel looper: a chain lift, a swooping first drop, then loop after loop. Simple, smooth and endlessly re-rideable, it anchors any big park.","image":"https://vignette.wikia.nocookie.net/rct/images/9/9b/Looping_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725171533"},{"name":"Twister Roller Coaster","rarity":"chase","id":"twister-roller-coaster","subtitle":"Roller Coaster","details":"A steel twister that knots itself into tight helices, corkscrews and tangled turns, trading huge drops for relentless direction changes and lateral fun.","image":"https://vignette.wikia.nocookie.net/rct/images/c/c3/Twister_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725173956"},{"name":"Wooden Roller Coaster","rarity":"chase","id":"wooden-roller-coaster","subtitle":"Roller Coaster","details":"Lumber, steel and glorious rattling charm. Trains clatter over timber hills with pops of airtime, delivering the noisy thrill only a true woodie can give.","image":"https://vignette.wikia.nocookie.net/rct/images/2/2a/Wooden_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725175853"},{"name":"Corkscrew Roller Coaster","rarity":"legendary","id":"corkscrew-roller-coaster","subtitle":"Roller Coaster","details":"A compact steel classic famed for its double corkscrew, twisting riders head over heels twice before a neat helix brings everyone back grinning.","image":"https://vignette.wikia.nocookie.net/rct/images/0/03/Corkscrew_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20141122112442"},{"name":"Hypercoaster","rarity":"legendary","id":"hypercoaster","subtitle":"Roller Coaster","details":"Built tall, fast and smooth, the hypercoaster lives for giant drops and floating airtime, with long trains gliding over hills in graceful succession.","image":"https://vignette.wikia.nocookie.net/rct/images/c/ca/Hypercoaster_RCT2_Icon.png/revision/latest?cb=20150725164929"},{"name":"LIM Launched Roller Coaster","rarity":"legendary","id":"lim-launched-roller-coaster","subtitle":"Roller Coaster","details":"Magnets do the climbing here: a LIM launch fires the train from the station in seconds, then sends it through loops and turns with no lift hill in sight.","image":"https://vignette.wikia.nocookie.net/rct/images/4/46/LIM_Launched_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725171449"},{"name":"Mine Train Coaster","rarity":"legendary","id":"mine-train-coaster","subtitle":"Roller Coaster","details":"Runaway mine cars rattle through tunnels, dips and banked turns at family-friendly speed, themed like a gold rush escape that never quite goes to plan.","image":"https://vignette.wikia.nocookie.net/rct/images/f/fc/Mine_Train_Coaster_RCT2_Icon.png/revision/latest?cb=20150601164136"},{"name":"Multi-Dimension Roller Coaster","rarity":"legendary","id":"multi-dimension-roller-coaster","subtitle":"Roller Coaster","details":"Seats rotate as the train races the track, so riders spin, flip and face new directions mid-ride. No two circuits ever feel quite the same for guests.","image":"https://vignette.wikia.nocookie.net/rct/images/0/04/Multi-Dimension_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20120701143606"},{"name":"Stand-up Roller Coaster","rarity":"legendary","id":"stand-up-roller-coaster","subtitle":"Roller Coaster","details":"Riders stand upright in bicycle-style seats for the whole circuit, tackling drops and a loop on their feet for a strangely intense, leg-testing thrill.","image":"https://vignette.wikia.nocookie.net/rct/images/4/41/Stand-up_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725171836"},{"name":"Vertical Drop Roller Coaster","rarity":"legendary","id":"vertical-drop-roller-coaster","subtitle":"Roller Coaster","details":"The train creeps over the edge, pauses over nothing, then plunges straight down. That vertical drop is short, terrifying and the entire point of the ride.","image":"https://vignette.wikia.nocookie.net/rct/images/d/d2/Vertical_Drop_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725175738"},{"name":"Air Powered Vertical Coaster","rarity":"epic","id":"air-powered-vertical-coaster","subtitle":"Roller Coaster","details":"Compressed air blasts the train skyward up a vertical spike, then lets gravity drop it right back down. Brief, violent and impossible for guests to ignore.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a1/Air_Powered_Vertical_Coaster_RCT2_Icon.png/revision/latest?cb=20141105202541"},{"name":"Compact Inverted Coaster","rarity":"epic","id":"compact-inverted-coaster","subtitle":"Roller Coaster","details":"A small-footprint inverted ride that folds loops and tight turns into a tight knot of track, perfect when space is scarce but thrills are still required.","image":"https://vignette.wikia.nocookie.net/rct/images/3/34/Compact_Inverted_Coaster_RCT2_Icon.png/revision/latest?cb=20141122112340"},{"name":"Flying Roller Coaster","rarity":"epic","id":"flying-roller-coaster","subtitle":"Roller Coaster","details":"Riders are tilted face-down beneath the train to soar like superheroes, swooping through pretzel loops and rolls with the ground spread out far below them.","image":"https://vignette.wikia.nocookie.net/rct/images/6/66/Flying_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725164936"},{"name":"Heartline Twister Coaster","rarity":"epic","id":"heartline-twister-coaster","subtitle":"Roller Coaster","details":"Trains thread through heartline rolls that spin riders around the track's own centre line, twisting in place while the compact layout keeps folding back.","image":"https://vignette.wikia.nocookie.net/rct/images/f/f3/Heartline_Twister_Coaster_RCT2_Icon.png/revision/latest?cb=20150725165029"},{"name":"Inverted Impulse Coaster","rarity":"epic","id":"inverted-impulse-coaster","subtitle":"Roller Coaster","details":"A launched shuttle that races forwards and backwards up two vertical spikes, twisting on one climb, while guests dangle inverted-style beneath the track.","image":"https://vignette.wikia.nocookie.net/rct/images/b/bb/Inverted_Impulse_Coaster_RCT2_Icon.png/revision/latest?cb=20150725165322"},{"name":"Reverse Freefall Coaster","rarity":"epic","id":"reverse-freefall-coaster","subtitle":"Roller Coaster","details":"One huge backwards climb, one helpless pause, then a freefall plunge back to the station. It does a single trick, but that trick empties stomachs reliably.","image":"https://vignette.wikia.nocookie.net/rct/images/1/1b/Reverse_Freefall_Coaster_RCT2_Icon.png/revision/latest?cb=20150725171945"},{"name":"Virginia Reel","rarity":"epic","id":"virginia-reel","subtitle":"Roller Coaster","details":"Spinning tubs trundle along a zig-zag wooden track, each car free to rotate as it clatters round the bends. A charming old-time ride with a dizzy streak.","image":"https://vignette.wikia.nocookie.net/rct/images/9/9a/Virginia_Reel_RCT2_Icon.png/revision/latest?cb=20150602140836"},{"name":"Water Coaster","rarity":"epic","id":"water-coaster","subtitle":"Roller Coaster","details":"Part coaster, part boat ride: trains climb and drop on steel track, then splash into water channels, soak their riders and climb straight back out again.","image":"https://vignette.wikia.nocookie.net/rct/images/e/e0/Water_Coaster_RCT2_Icon.png/revision/latest?cb=20150622170157"},{"name":"Bobsleigh Coaster","rarity":"rare","id":"bobsleigh-coaster","subtitle":"Roller Coaster","details":"Trains sit loose in a half-pipe trough instead of on rails, banking and sliding side to side like a real bobsled run as they gather speed down the course.","image":"https://vignette.wikia.nocookie.net/rct/images/1/11/Bobsleigh_Coaster_RCT2_Icon.png/revision/latest?cb=20141122111608"},{"name":"Floorless Roller Coaster","rarity":"rare","id":"floorless-roller-coaster","subtitle":"Roller Coaster","details":"The Twister's floorless trains leave riders' legs dangling over the track, adding wide-open exposure to every loop, roll and sweeping drop along the way.","image":"https://vignette.wikia.nocookie.net/rct/images/5/5a/Floorless_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725173916"},{"name":"Inverted Hairpin Coaster","rarity":"rare","id":"inverted-hairpin-coaster","subtitle":"Roller Coaster","details":"An inverted take on the wild mouse idea, with dangling trains whipping round tight hairpin turns and sudden drops that catch first-time riders off guard.","image":"https://vignette.wikia.nocookie.net/rct/images/e/ea/Inverted_Hairpin_Coaster_RCT2_Icon.png/revision/latest?cb=20150602141118"},{"name":"Inverted Shuttle Coaster","rarity":"rare","id":"inverted-shuttle-coaster","subtitle":"Roller Coaster","details":"The Compact Inverted's shuttle form runs its tight, loopy layout forwards then backwards, squeezing two different-feeling rides out of one small footprint.","image":"https://vignette.wikia.nocookie.net/rct/images/e/e0/Inverted_Shuttle_Coaster_RCT2_Icon.png/revision/latest?cb=20150708230458"},{"name":"Lay-down Roller Coaster","rarity":"rare","id":"lay-down-roller-coaster","subtitle":"Roller Coaster","details":"Riders recline on their backs or stomachs for the whole circuit, gliding through gentle rolls and turns in a laid-back pose that feels oddly like flying.","image":"https://vignette.wikia.nocookie.net/rct/images/3/38/Lay-down_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150602141506"},{"name":"Mini Suspended Coaster","rarity":"rare","id":"mini-suspended-coaster","subtitle":"Roller Coaster","details":"Small cars hang and swing gently beneath the track, giving younger guests a mild, swooping tour of the park without the drops or loops of its bigger kin.","image":"https://vignette.wikia.nocookie.net/rct/images/a/ab/Mini_Suspended_Coaster_RCT2_Icon.png/revision/latest?cb=20150725171645"},{"name":"Spiral Roller Coaster","rarity":"rare","id":"spiral-roller-coaster","subtitle":"Roller Coaster","details":"A gentle steel coaster built around a long, winding spiral descent. It trades loops and drama for a smooth, scenic glide that nearly every guest can enjoy.","image":"https://vignette.wikia.nocookie.net/rct/images/7/73/Spiral_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725171829"},{"name":"Steeplechase","rarity":"rare","id":"steeplechase","subtitle":"Roller Coaster","details":"Riders straddle horse-shaped vehicles on a single rail and race side by side over jumps and dips, leaning into the chase like jockeys in a friendly derby.","image":"https://vignette.wikia.nocookie.net/rct/images/c/c0/Steeplechase_RCT2_Icon.png/revision/latest?cb=20150725175501"},{"name":"Suspended Swinging Coaster","rarity":"rare","id":"suspended-swinging-coaster","subtitle":"Roller Coaster","details":"Cars hang below the track on swinging arms, swaying wide through every turn in its default swinging cars. Smooth, swooping and beloved by thrill-seekers.","image":"https://vignette.wikia.nocookie.net/rct/images/5/55/Suspended_Swinging_Cars_RCT2_Icon.png/revision/latest?cb=20150725175518"},{"name":"Wooden Wild Mouse","rarity":"rare","id":"wooden-wild-mouse","subtitle":"Roller Coaster","details":"A timber mouse with sharp hairpin turns and sudden dips, its wooden frame adding extra rattle and charm to every near-miss with the structure whizzing by.","image":"https://vignette.wikia.nocookie.net/rct/images/e/e6/Wooden_Wild_Mouse_RCT2_Icon.png/revision/latest?cb=20150725175905"},{"name":"Articulated Roller Coaster","rarity":"uncommon","id":"articulated-roller-coaster","subtitle":"Roller Coaster","details":"A jointed train style for the Wooden Roller Coaster, built to flex smoothly through timber twists and turns while keeping the classic woodie rattle alive.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a8/Articulated_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725175836"},{"name":"Hyper-Twister","rarity":"uncommon","id":"hyper-twister","subtitle":"Roller Coaster","details":"A taller, faster cousin of the Twister, stretching its tangled helices and corkscrews over a much bigger layout built for speed as well as endless turning.","image":"https://vignette.wikia.nocookie.net/rct/images/b/b1/Hyper-Twister_RCT2_Icon.png/revision/latest?cb=20150725173914"},{"name":"Junior Roller Coaster","rarity":"uncommon","id":"junior-roller-coaster","subtitle":"Roller Coaster","details":"A gentle first coaster for younger guests, with small hills and easy turns. Its ladybird trains trundle round in cheerful loops that invite instant re-rides.","image":"https://vignette.wikia.nocookie.net/rct/images/e/e1/Ladybird_Trains_RCT2_Icon.png/revision/latest?cb=20150725165410"},{"name":"Mine Ride","rarity":"uncommon","id":"mine-ride","subtitle":"Roller Coaster","details":"The mine-train cars of the Mine Train Coaster, rattling guests through dips and tunnels like a runaway gold rush escape that is big on charm, light on fear.","image":"https://vignette.wikia.nocookie.net/rct/images/4/49/Mine_Ride_RCT2_Icon.png/revision/latest?cb=20150725171541"},{"name":"Mini Roller Coaster","rarity":"uncommon","id":"mini-roller-coaster","subtitle":"Roller Coaster","details":"A pint-sized steel coaster of tight turns and bunny hops, fronted by its automobile cars. Small in stature, but it still packs a lively punch for its size.","image":"https://vignette.wikia.nocookie.net/rct/images/f/f6/Automobile_Cars_RCT2_Icon.png/revision/latest?cb=20150725171442"},{"name":"Mini Suspended Flying Coaster","rarity":"uncommon","id":"mini-suspended-flying-coaster","subtitle":"Roller Coaster","details":"A flying variant for the Mini Suspended Coaster, tilting its small hanging cars so riders swoop face-forward, gently soaring over the paths below the track.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a3/Mini_Suspended_Flying_Coaster_RCT2_Icon.png/revision/latest?cb=20150725171622"},{"name":"Reverser Roller Coaster","rarity":"uncommon","id":"reverser-roller-coaster","subtitle":"Roller Coaster","details":"Mid-ride, the cars swivel round so guests finish the circuit travelling backwards. That one sneaky reversal turns a mild layout into a disorienting delight.","image":"https://vignette.wikia.nocookie.net/rct/images/7/73/Reverser_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150602142136"},{"name":"Side-Friction Roller Coaster","rarity":"uncommon","id":"side-friction-roller-coaster","subtitle":"Roller Coaster","details":"An old-school wooden design where a brakeman's craft and side wheels keep the train on track, giving a loose, rattly ride full of vintage fairground charm.","image":"https://vignette.wikia.nocookie.net/rct/images/2/29/Side-Friction_Roller_Coaster_RCT2_Icon.png/revision/latest?cb=20150725171841"},{"name":"Spinning Wild Mouse","rarity":"uncommon","id":"spinning-wild-mouse","subtitle":"Roller Coaster","details":"A Wild Mouse family spinner whose cars rotate freely as they whip round hairpins, so every ride mixes sharp turns with a fresh, unpredictable dose of spin.","image":"https://vignette.wikia.nocookie.net/rct/images/b/be/Spinning_Wild_Mouse_RCT2_Icon.png/revision/latest?cb=20150725175801"},{"name":"Stand-up Twister Coaster","rarity":"uncommon","id":"stand-up-twister-coaster","subtitle":"Roller Coaster","details":"A stand-up train option for the Twister Roller Coaster, sending riders upright through its helices and corkscrews for a tangled circuit tackled on two feet.","image":"https://vignette.wikia.nocookie.net/rct/images/8/85/Stand-up_Twister_Coaster_RCT2_Icon.png/revision/latest?cb=20150725173952"},{"name":"Suspended Swinging Airplane Cars","rarity":"uncommon","id":"suspended-swinging-airplane-cars","subtitle":"Roller Coaster","details":"Biplane-styled cars for the Suspended Swinging Coaster, hanging below the track and banking through turns as if dogfighting gently high above the park paths.","image":"https://vignette.wikia.nocookie.net/rct/images/9/9a/Suspended_Swinging_Airplane_Cars_RCT2_Icon.png/revision/latest?cb=20150725175513"},{"name":"Wooden Wild Mine Ride","rarity":"uncommon","id":"wooden-wild-mine-ride","subtitle":"Roller Coaster","details":"Mine-themed cars for the Wooden Wild Mouse, rattling round its hairpins and dips as if escaping a timber-framed mine that was never built to safety standards.","image":"https://vignette.wikia.nocookie.net/rct/images/c/c1/Wooden_Wild_Mine_Ride_RCT2_Icon.png/revision/latest?cb=20150725175900"},{"name":"Flying Turns","rarity":"common","id":"flying-turns","subtitle":"Roller Coaster","details":"A train option for the Bobsleigh Coaster that slides loose in the trough, banking high on the turns like an old wooden flying turns ride from fairground days.","image":"https://vignette.wikia.nocookie.net/rct/images/4/41/Flying_Turns_RCT2_Icon.png/revision/latest?cb=20150708230219"},{"name":"Heartline Twister Coaster (starting reversed)","rarity":"common","id":"heartline-twister-coaster-starting-reversed","subtitle":"Roller Coaster","details":"The Heartline Twister variant that starts its run backwards, sending riders into its heartline rolls facing reversed before the twisting has even settled in.","image":"https://vignette.wikia.nocookie.net/rct/images/a/af/Heartline_Twister_Coaster_%28starting_reversed%29_RCT2_Icon.png/revision/latest?cb=20161030201234"},{"name":"Inverted Vertical Shuttle","rarity":"common","id":"inverted-vertical-shuttle","subtitle":"Roller Coaster","details":"A shuttle train for the Compact Inverted Coaster, launching riders up a vertical spike and back down again with their feet dangling free beneath the track.","image":"https://vignette.wikia.nocookie.net/rct/images/d/d7/Inverted_Vertical_Shuttle_RCT2_Icon.png/revision/latest?cb=20150708230503"},{"name":"Log Trains","rarity":"common","id":"log-trains","subtitle":"Roller Coaster","details":"Hollowed-log trains for the Junior Roller Coaster, giving its gentle hills and turns a woodland storybook feel that suits younger riders down to the ground.","image":"https://vignette.wikia.nocookie.net/rct/images/6/6e/Log_Trains_RCT2_Icon.png/revision/latest?cb=20150725165504"},{"name":"Mine Cars","rarity":"common","id":"mine-cars","subtitle":"Roller Coaster","details":"Ore-filled mine cars for the Wild Mouse family, clattering round hairpin turns and sudden dips as if the whole load might spill on every single switchback.","image":"https://vignette.wikia.nocookie.net/rct/images/e/ee/Mine_Cars_RCT2_Icon.png/revision/latest?cb=20150725175750"},{"name":"Motorbike Races","rarity":"common","id":"motorbike-races","subtitle":"Roller Coaster","details":"Motorbike vehicles for the Steeplechase, letting riders lean over the bars and race side by side over the jumps as if chasing the chequered flag at full tilt.","image":"https://vignette.wikia.nocookie.net/rct/images/8/84/Motorbike_Races_RCT2_Icon.png/revision/latest?cb=20150725175406"},{"name":"Rocket Cars","rarity":"common","id":"rocket-cars","subtitle":"Roller Coaster","details":"Sleek rocket cars for the Mini Roller Coaster, adding futuristic flair to its tight turns and bunny hops. Small ride, big imagination, endless pretend launches.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a5/Rocket_Cars_RCT2_Icon.png/revision/latest?cb=20150725171608"},{"name":"Soap Box Derby Racers","rarity":"common","id":"soap-box-derby-racers","subtitle":"Roller Coaster","details":"Home-built soap box racers for the Steeplechase, racing wheel to wheel over dips and jumps in a cheerful nod to every gravity-powered derby ever run downhill.","image":"https://vignette.wikia.nocookie.net/rct/images/c/c6/Soap_Box_Derby_Racers_RCT2_Icon.png/revision/latest?cb=20150725175353"},{"name":"Swinging Floorless Cars","rarity":"common","id":"swinging-floorless-cars","subtitle":"Roller Coaster","details":"Floorless swinging cars for the Suspended Swinging Coaster, leaving riders' legs free as the cars sway wide through turns with nothing beneath their feet.","image":"https://vignette.wikia.nocookie.net/rct/images/4/44/Swinging_Floorless_Cars_RCT2_Icon.png/revision/latest?cb=20150725175524"},{"name":"Toboggan Cars","rarity":"common","id":"toboggan-cars","subtitle":"Roller Coaster","details":"Enclosed toboggan cars for the Mini Roller Coaster, cosy little capsules that zip round its tight bends and hops like a winter sled run that never melts away.","image":"https://vignette.wikia.nocookie.net/rct/images/8/8c/Toboggan_Cars_RCT2_Icon.png/revision/latest?cb=20150725171614"},{"name":"Wild Mouse","rarity":"common","id":"wild-mouse","subtitle":"Roller Coaster","details":"Tiny mouse cars dart round unbanked hairpin turns high on a zig-zag track, each corner feeling like it might tip. Its default mouse cars define the classic ride.","image":"https://vignette.wikia.nocookie.net/rct/images/8/80/Mouse_Cars_RCT2_Icon.png/revision/latest?cb=20150725175755"},{"name":"Wooden Roller Coaster (6 seater)","rarity":"common","id":"wooden-roller-coaster-6-seater","subtitle":"Roller Coaster","details":"A longer six-seater train option for the Wooden Roller Coaster, carrying more guests per dispatch while keeping every clatter, rattle and pop of airtime intact.","image":"https://vignette.wikia.nocookie.net/rct/images/f/f8/Wooden_Roller_Coaster_%286_seater%29_RCT2_Icon.png/revision/latest?cb=20150804225026"},{"name":"Wooden Roller Coaster (6 seater, Reversed)","rarity":"common","id":"wooden-roller-coaster-6-seater-reversed","subtitle":"Roller Coaster","details":"The reversed six-seater train for the Wooden Roller Coaster, facing riders backwards over every hill so the drops arrive unseen and the rattle feels wilder.","image":"https://vignette.wikia.nocookie.net/rct/images/d/d0/Wooden_Roller_Coaster_%286_seater%2C_Reversed%29_RCT2_Icon.png/revision/latest?cb=20150804225033"},{"name":"Merry-Go-Round","rarity":"chase","id":"merry-go-round","subtitle":"Gentle Ride","details":"The park classic: painted horses rise and fall in endless circles to cheerful music. It is pure nostalgia, and every guest finds it calming and charming.","image":"https://vignette.wikia.nocookie.net/rct/images/7/7f/Merry-Go-Round_RCT2_Icon.png/revision/latest?cb=20150531121522"},{"name":"Ferris Wheel","rarity":"legendary","id":"ferris-wheel","subtitle":"Gentle Ride","details":"A slow-turning giant wheel lifts guests high above the park for sweeping views. It barely thrills anyone, but as a landmark and photo spot it is unbeatable.","image":"https://vignette.wikia.nocookie.net/rct/images/0/0b/Ferris_Wheel_RCT2_Icon.png/revision/latest?cb=20150531121029"},{"name":"Haunted House","rarity":"legendary","id":"haunted-house","subtitle":"Gentle Ride","details":"A walk-through of creaky rooms, spooky props and jumpy surprises behind every door. It delivers gentle chills without a single drop, spin or fast corner.","image":"https://vignette.wikia.nocookie.net/rct/images/0/06/Haunted_House_RCT2_Icon.png/revision/latest?cb=20150531121205"},{"name":"Maze","rarity":"legendary","id":"maze","subtitle":"Gentle Ride","details":"A hedge maze that guests wander, backtrack and puzzle their way through at their own pace. Getting lost is the whole point, and finding the exit feels earned.","image":"https://vignette.wikia.nocookie.net/rct/images/2/24/Maze_RCT2_Icon.png/revision/latest?cb=20150531121434"},{"name":"Dodgems","rarity":"epic","id":"dodgems","subtitle":"Gentle Ride","details":"Guests take the wheel of little electric cars and gleefully bump, spin and chase each other around the floor. Friendly chaos, low speed and endless grins.","image":"https://vignette.wikia.nocookie.net/rct/images/1/19/Dodgems_RCT2_Icon.png/revision/latest?cb=20141122113122"},{"name":"Ghost Train","rarity":"epic","id":"ghost-train","subtitle":"Gentle Ride","details":"A dark ride where little cars roll past ghosts, skeletons and creaking surprises in the dark. Spooky rather than scary, it is a gentle ride with real theatre.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a6/Ghost_Train_RCT2_Icon.png/revision/latest?cb=20150531140541"},{"name":"Mini Golf","rarity":"epic","id":"mini-golf","subtitle":"Gentle Ride","details":"A pay-per-play course of windmills, loops and tricky little slopes that guests tackle with a putter. It earns money hole by hole and charms competitive groups.","image":"https://vignette.wikia.nocookie.net/rct/images/9/99/Mini_Golf_RCT2_Icon.png/revision/latest?cb=20150531140830"},{"name":"Circus","rarity":"rare","id":"circus","subtitle":"Gentle Ride","details":"A big-top show of acrobats, clowns and performing animals that guests watch from the stands. No track, no queue drama - just a cheerful break from the rides.","image":"https://vignette.wikia.nocookie.net/rct/images/c/c1/Circus_RCT2_Icon.png/revision/latest?cb=20141122112228"},{"name":"Crooked House","rarity":"rare","id":"crooked-house","subtitle":"Gentle Ride","details":"A topsy-turvy walk-through where floors tilt, walls lean and furniture defies gravity. Guests stumble out laughing at how strange a simple room can feel.","image":"https://vignette.wikia.nocookie.net/rct/images/9/9e/Crooked_House_RCT2_Icon.png/revision/latest?cb=20141122112540"},{"name":"Double-deck Observation Tower","rarity":"rare","id":"double-deck-observation-tower","subtitle":"Gentle Ride","details":"The Observation Tower grown taller, with two stacked decks of guests rising and slowly rotating. The higher cabin gives an even grander view over the park.","image":"https://vignette.wikia.nocookie.net/rct/images/9/91/Double-deck_Observation_Tower_RCT2_Icon.png/revision/latest?cb=20141122113213"},{"name":"Flying Saucers","rarity":"rare","id":"flying-saucers","subtitle":"Gentle Ride","details":"Guests pilot little saucer cars that glide and bump gently around a smooth floor. Easy to steer, hard to master, and wonderfully silly for all ages.","image":"https://vignette.wikia.nocookie.net/rct/images/4/45/Flying_Saucers_RCT2_Icon.png/revision/latest?cb=20150531140701"},{"name":"Observation Tower","rarity":"rare","id":"observation-tower","subtitle":"Gentle Ride","details":"A tall tower that lifts a rotating cabin of guests high into the sky and back down again. It is all about the view, making it a calm highlight in any park.","image":"https://vignette.wikia.nocookie.net/rct/images/9/9c/Observation_Tower_RCT2_Icon.png/revision/latest?cb=20150601112359"},{"name":"Spiral Slide","rarity":"rare","id":"spiral-slide","subtitle":"Gentle Ride","details":"Guests grab a mat, climb to the top and whoosh down a long helter-skelter spiral. A fairground staple that is simple, speedy and gentle enough for everyone.","image":"https://vignette.wikia.nocookie.net/rct/images/f/f8/Spiral_Slide_RCT2_Icon.png/revision/latest?cb=20150531122217"},{"name":"Car Ride","rarity":"uncommon","id":"car-ride","subtitle":"Gentle Ride","details":"Guests drive sportscars themselves along a winding track at a stately, safe pace. In its default sportscars it feels like a scenic tour you get to steer.","image":"https://vignette.wikia.nocookie.net/rct/images/5/52/Sportscars_RCT2_Icon.png/revision/latest?cb=20150708084040"},{"name":"Haunted Mansion Ride","rarity":"uncommon","id":"haunted-mansion-ride","subtitle":"Gentle Ride","details":"The Ghost Train's grander sibling, a larger haunted dark ride with bigger rooms and bolder scares. It trades the little cars for a more imposing mansion tour.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a3/Haunted_Mansion_Ride_RCT2_Icon.png/revision/latest?cb=20150601220500"},{"name":"Mini Helicopters","rarity":"uncommon","id":"mini-helicopters","subtitle":"Gentle Ride","details":"Little helicopters circle a central tower, and guests can pedal or control their height as they fly. A cheerful flying ride that feels personal and playful.","image":"https://vignette.wikia.nocookie.net/rct/images/5/53/Mini_Helicopters_RCT2_Icon.png/revision/latest?cb=20150531140424"},{"name":"Monorail Cycles","rarity":"uncommon","id":"monorail-cycles","subtitle":"Gentle Ride","details":"Guests pedal their own little cycles along an elevated monorail beam, as fast or slow as they like. The workout is optional, but the treetop views are not.","image":"https://vignette.wikia.nocookie.net/rct/images/8/85/Monorail_Cycles_RCT2_Icon.png/revision/latest?cb=20150531140210"},{"name":"Space Rings","rarity":"uncommon","id":"space-rings","subtitle":"Gentle Ride","details":"Guests climb inside big gyroscopic rings and spin themselves in every direction like trainee astronauts. Self-powered, dizzying and oddly hard to stop smiling about.","image":"https://vignette.wikia.nocookie.net/rct/images/0/05/Space_Rings_RCT2_Icon.png/revision/latest?cb=20150531122029"},{"name":"Cheshire Cats","rarity":"common","id":"cheshire-cats","subtitle":"Gentle Ride","details":"A Car Ride vehicle option with grinning Cheshire cat cars leading the tour. They turn a gentle drive into a storybook trip with a very wide smile up front.","image":"https://vignette.wikia.nocookie.net/rct/images/b/b7/Cheshire_Cats_RCT2_Icon.png/revision/latest?cb=20141122112127"},{"name":"Monster Trucks","rarity":"common","id":"monster-trucks","subtitle":"Gentle Ride","details":"A Car Ride vehicle option using chunky monster trucks with huge tyres. They lumber over the track looking mighty, even at the ride's usual gentle pace.","image":"https://vignette.wikia.nocookie.net/rct/images/9/94/Monster_Trucks_RCT2_Icon.png/revision/latest?cb=20150628204515"},{"name":"Pickup Trucks","rarity":"common","id":"pickup-trucks","subtitle":"Gentle Ride","details":"A Car Ride vehicle option of friendly pickup trucks for the scenic drive. They give the tour a hardworking, countryside feel that suits woodland parks well.","image":"https://vignette.wikia.nocookie.net/rct/images/c/ca/Pickup_Trucks_RCT2_Icon.png/revision/latest?cb=20150628204500"},{"name":"Racing Cars","rarity":"common","id":"racing-cars","subtitle":"Gentle Ride","details":"A Car Ride vehicle option styled like proper racing cars, all stripes and spoilers. They look fast standing still, though the drive itself stays nice and calm.","image":"https://vignette.wikia.nocookie.net/rct/images/5/52/Racing_Cars_RCT2_Icon.png/revision/latest?cb=20150628204451"},{"name":"Vintage Cars","rarity":"common","id":"vintage-cars","subtitle":"Gentle Ride","details":"A Car Ride vehicle option of elegant vintage automobiles from motoring's early days. They make the gentle tour feel like a parade through a bygone era.","image":"https://vignette.wikia.nocookie.net/rct/images/1/17/Vintage_Cars_RCT2_Icon.png/revision/latest?cb=20150628204508"},{"name":"Pirate Ship","rarity":"chase","id":"pirate-ship","subtitle":"Thrill Ride","details":"A great galleon swings higher and higher until it nearly stands on end. Simple, scream-filled and spectacular, it is the thrill ride every park needs first.","image":"https://vignette.wikia.nocookie.net/rct/images/6/63/Pirate_Ship_RCT2_Icon.png/revision/latest?cb=20150531134957"},{"name":"Go Karts","rarity":"legendary","id":"go-karts","subtitle":"Thrill Ride","details":"Guests race real little karts around a twisting circuit, fighting for the lead on every corner. Competitive, noisy and replayable, it is a thrill with a steering wheel.","image":"https://vignette.wikia.nocookie.net/rct/images/1/17/Go_Karts_RCT2_Icon.png/revision/latest?cb=20150531123634"},{"name":"Launched Freefall","rarity":"legendary","id":"launched-freefall","subtitle":"Thrill Ride","details":"A tower that blasts guests straight up at speed, lets them hang weightless a moment, then drops them back down. Brief, brutal and brilliant for adrenaline fans.","image":"https://vignette.wikia.nocookie.net/rct/images/5/50/Launched_Freefall_RCT2_Icon.png/revision/latest?cb=20150531135233"},{"name":"Enterprise","rarity":"epic","id":"enterprise","subtitle":"Thrill Ride","details":"A spinning wheel of gondolas that tilts up until it stands almost vertical, pinning riders in place with pure force. Intense, disorienting and strangely graceful.","image":"https://vignette.wikia.nocookie.net/rct/images/1/14/Enterprise_RCT2_Icon.png/revision/latest?cb=20150531141543"},{"name":"Roto-Drop","rarity":"epic","id":"roto-drop","subtitle":"Thrill Ride","details":"Guests ride a ring of seats to the top of a tall tower, pause to admire the view, then plummet in freefall. The wait at the top is half the terror.","image":"https://vignette.wikia.nocookie.net/rct/images/f/ff/Roto-Drop_RCT2_Icon.png/revision/latest?cb=20150531141059"},{"name":"Swinging Inverter Ship","rarity":"epic","id":"swinging-inverter-ship","subtitle":"Thrill Ride","details":"Like a pirate ship with a vicious twist: the gondola loops right over the top and hangs guests upside down. It swings, inverts and rarely lets nausea stay low.","image":"https://vignette.wikia.nocookie.net/rct/images/3/32/Swinging_Inverter_Ship_RCT2_Icon.png/revision/latest?cb=20150531134659"},{"name":"Motion Simulator","rarity":"rare","id":"motion-simulator","subtitle":"Thrill Ride","details":"A cinema cabin that tilts, shakes and dives in time with the film on screen. Guests feel a wild ride unfold around them without the cabin ever leaving the room.","image":"https://vignette.wikia.nocookie.net/rct/images/8/81/Motion_Simulator_RCT2_Icon.png/revision/latest?cb=20150531131736"},{"name":"Top Spin","rarity":"rare","id":"top-spin","subtitle":"Thrill Ride","details":"A long bench of guests is lifted, swung and rolled through somersaults above a fountain-ready floor. Every cycle is different, and few riders keep their stomachs calm.","image":"https://vignette.wikia.nocookie.net/rct/images/1/1e/Top_Spin_RCT2_Icon.png/revision/latest?cb=20150531124030"},{"name":"3D Cinema","rarity":"uncommon","id":"3d-cinema","subtitle":"Thrill Ride","details":"Guests put on special glasses and watch a film that leaps right off the screen. It is a seated thrill, easy to place and a welcome rest that still excites.","image":"https://vignette.wikia.nocookie.net/rct/images/7/76/3D_Cinema_RCT2_Icon.png/revision/latest?cb=20141105202434"},{"name":"Twist","rarity":"uncommon","id":"twist","subtitle":"Thrill Ride","details":"Rows of spinning cups whirl around a turning platform while guests crank their own wheel to spin faster. A classic recipe for laughter, dizziness and mild nausea.","image":"https://vignette.wikia.nocookie.net/rct/images/f/f7/Twist_RCT2_Icon.png/revision/latest?cb=20150628202300"},{"name":"Magic Carpet","rarity":"common","id":"magic-carpet","subtitle":"Thrill Ride","details":"A flying carpet platform swings guests back and forth in big, swooping arcs. It feels like soaring over a desert city, with just enough height to thrill.","image":"https://vignette.wikia.nocookie.net/rct/images/9/95/Magic_Carpet_RCT2_Icon.png/revision/latest?cb=20150622195604"},{"name":"Snow Cups","rarity":"common","id":"snow-cups","subtitle":"Thrill Ride","details":"A winter-skinned version of the Twist, trading the cups for snowy sled-style cars on a frosty platform. Same joyful spinning, wrapped in a cosy alpine theme.","image":"https://vignette.wikia.nocookie.net/rct/images/d/d1/Snow_Cups_RCT2_Icon.png/revision/latest?cb=20150628202250"},{"name":"Log Flume","rarity":"chase","id":"log-flume","subtitle":"Water Ride","details":"Log boats drift along water channels, climb quiet lifts, then plunge down drops into a soaking splash. The final drop is the photo moment every guest braces for.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a1/Log_Flume_RCT2_Icon.png/revision/latest?cb=20150531000221"},{"name":"River Rapids","rarity":"legendary","id":"river-rapids","subtitle":"Water Ride","details":"Round rafts bounce and spin through churning rapids, waterfalls and soaking surprises. No two rides soak the same guests, which is exactly why groups love it.","image":"https://vignette.wikia.nocookie.net/rct/images/4/4d/River_Rapids_RCT2_Icon.png/revision/latest?cb=20150531135614"},{"name":"Splash Boats","rarity":"legendary","id":"splash-boats","subtitle":"Water Ride","details":"Boats glide around a scenic water circuit before a lift and a mighty plunge send a wave over everyone aboard. Part sightseeing tour, part guaranteed soaking.","image":"https://vignette.wikia.nocookie.net/rct/images/8/86/Splash_Boats_RCT2_Icon.png/revision/latest?cb=20150622165612"},{"name":"Dinghy Slide","rarity":"epic","id":"dinghy-slide","subtitle":"Water Ride","details":"Guests carry inflatable dinghies up and slide down a winding water chute, spinning as they go. Compact, splashy and endlessly re-ridable on a hot park day.","image":"https://vignette.wikia.nocookie.net/rct/images/d/d3/Dinghy_Slide_RCT2_Icon.png/revision/latest?cb=20141122112556"},{"name":"River Rafts","rarity":"epic","id":"river-rafts","subtitle":"Water Ride","details":"A gentler take on white water, with rafts drifting and bobbing along a lively river course. It soaks a little, thrills a little and suits a wider crowd.","image":"https://vignette.wikia.nocookie.net/rct/images/e/e1/River_Rafts_RCT2_Icon.png/revision/latest?cb=20150622165752"},{"name":"Boat Hire","rarity":"rare","id":"boat-hire","subtitle":"Water Ride","details":"Guests take rowing boats out onto the lake and paddle wherever they please. In its default rowing boats it is peaceful, scenic and entirely guest-powered.","image":"https://vignette.wikia.nocookie.net/rct/images/0/05/Rowing_Boats_RCT2_Icon.png/revision/latest?cb=20150628203427"},{"name":"Bumper Boats","rarity":"rare","id":"bumper-boats","subtitle":"Water Ride","details":"A Boat Hire option where the boats are built for bumping, with guests gleefully crashing on the water. Slower than dodgems, wetter and every bit as silly.","image":"https://vignette.wikia.nocookie.net/rct/images/9/9c/Bumper_Boats_RCT2_Icon.png/revision/latest?cb=20141122111629"},{"name":"Submarine Ride","rarity":"rare","id":"submarine-ride","subtitle":"Water Ride","details":"A submarine dives guests beneath the water to glide past coral, wrecks and sea creatures. It is a calm underwater voyage that feels like a real expedition.","image":"https://vignette.wikia.nocookie.net/rct/images/9/99/Submarine_Ride_RCT2_Icon.png/revision/latest?cb=20150622170713"},{"name":"Canoes","rarity":"uncommon","id":"canoes","subtitle":"Water Ride","details":"A Boat Hire option of sleek canoes for paddling the lake. They feel sportier and more adventurous than the rowing boats, perfect for exploring far corners.","image":"https://vignette.wikia.nocookie.net/rct/images/b/b8/Canoes_RCT2_Icon.png/revision/latest?cb=20141122111812"},{"name":"Jet Skis","rarity":"uncommon","id":"jet-skis","subtitle":"Water Ride","details":"A Boat Hire option that swaps paddles for engines, letting guests zip across the lake on jet skis. By far the liveliest way to hire a boat in the park.","image":"https://vignette.wikia.nocookie.net/rct/images/d/df/Jet_Skis_RCT2_Icon.png/revision/latest?cb=20150628203413"},{"name":"Swans","rarity":"common","id":"swans","subtitle":"Water Ride","details":"A Boat Hire option of graceful swan boats, pedalled gently around the lake. They are romantic, photogenic and about as relaxing as a ride can possibly be.","image":"https://vignette.wikia.nocookie.net/rct/images/4/4d/Swans_RCT2_Icon.png/revision/latest?cb=20150628203436"},{"name":"Water Tricycles","rarity":"common","id":"water-tricycles","subtitle":"Water Ride","details":"A Boat Hire option of pedal tricycles that ride on big floating wheels. Wobbly, cheerful and harder work than they look, they charm everyone who tries them.","image":"https://vignette.wikia.nocookie.net/rct/images/5/51/Water_Tricycles_RCT2_Icon.png/revision/latest?cb=20150628203442"},{"name":"Miniature Railway","rarity":"legendary","id":"miniature-railway","subtitle":"Transport Ride","details":"A charming little railway that carries guests around the park in style, station to station. It is transport, sightseeing and pure nostalgia all in one loop.","image":"https://vignette.wikia.nocookie.net/rct/images/3/37/Miniature_Railway_RCT1_Icon.png/revision/latest?cb=20150622161816"},{"name":"Steam Trains","rarity":"epic","id":"steam-trains","subtitle":"Transport Ride","details":"A Miniature Railway train option of classic steam locomotives pulling open carriages. All puff and whistle, they are the timeless look for a park railway.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a8/Steam_Trains_RCT2_Icon.png/revision/latest?cb=20150628195219"},{"name":"Suspended Monorail","rarity":"epic","id":"suspended-monorail","subtitle":"Transport Ride","details":"A sleek train hangs beneath its elevated beam and glides silently around the park. Futuristic and smooth, it turns getting around into a ride in itself.","image":"https://vignette.wikia.nocookie.net/rct/images/e/ed/Suspended_Monorail_RCT2_Icon.png/revision/latest?cb=20150622163218"},{"name":"Chairlift","rarity":"rare","id":"chairlift","subtitle":"Transport Ride","details":"Guests ride open chairs carried by cable high above the park, legs dangling in the breeze. With its standard Chairlift Cars it is transport with a view.","image":"https://vignette.wikia.nocookie.net/rct/images/c/c9/Chairlift_Cars_RCT2_Icon.png/revision/latest?cb=20150628195017"},{"name":"Monorail","rarity":"rare","id":"monorail","subtitle":"Transport Ride","details":"A futuristic train glides along an elevated beam, carrying guests cleanly across the park. With its default Streamlined trains it looks fast even standing still.","image":"https://vignette.wikia.nocookie.net/rct/images/2/24/Streamlined_Monorail_Trains_RCT2_Icon.png/revision/latest?cb=20150628195304"},{"name":"Trams","rarity":"rare","id":"trams","subtitle":"Transport Ride","details":"Friendly tram cars trundle along their route, picking up and dropping off guests around the park. Old-fashioned, practical and full of street-level charm.","image":"https://vignette.wikia.nocookie.net/rct/images/c/cd/Trams_RCT2_Icon.png/revision/latest?cb=20150628195230"},{"name":"Lift","rarity":"uncommon","id":"lift","subtitle":"Transport Ride","details":"A vertical transport tower that carries guests between levels of the park in a rising cabin. Simple and useful, it saves a lot of walking on hilly terrain.","image":"https://vignette.wikia.nocookie.net/rct/images/6/60/Lift_RCT2_Icon.png/revision/latest?cb=20150622163352"},{"name":"Retro-style Monorail Trains","rarity":"uncommon","id":"retro-style-monorail-trains","subtitle":"Transport Ride","details":"A Monorail train option with rounded, retro styling from a cheerier age of the future. They give the elevated route a nostalgic, storybook character.","image":"https://vignette.wikia.nocookie.net/rct/images/3/33/Retro-style_Monorail_Trains_RCT2_Icon.png/revision/latest?cb=20150628195309"},{"name":"Small Monorail Cars","rarity":"uncommon","id":"small-monorail-cars","subtitle":"Transport Ride","details":"A Monorail train option of compact little cars instead of one long train. They feel personal and nimble, suiting smaller parks and tighter circuits.","image":"https://vignette.wikia.nocookie.net/rct/images/c/c6/Small_Monorail_Cars_RCT2_Icon.png/revision/latest?cb=20150628195258"},{"name":"American Style Steam Trains","rarity":"common","id":"american-style-steam-trains","subtitle":"Transport Ride","details":"A Miniature Railway train option of big American steam locomotives, cowcatchers and all. They bring a frontier railroad grandeur to the park circuit.","image":"https://vignette.wikia.nocookie.net/rct/images/b/ba/American_Style_Steam_Trains_RCT2_Icon.png/revision/latest?cb=20150628195057"},{"name":"Ski-lift Chairs","rarity":"common","id":"ski-lift-chairs","subtitle":"Transport Ride","details":"A Chairlift chair option styled like ski-lift seats, built for alpine parks. They make the cable ride feel like a trip up a snowy mountain slope.","image":"https://vignette.wikia.nocookie.net/rct/images/3/34/Ski-lift_Chairs_RCT2_Icon.png/revision/latest?cb=20150628195022"},{"name":"Steam Trains with Covered Cars","rarity":"common","id":"steam-trains-with-covered-cars","subtitle":"Transport Ride","details":"A Miniature Railway train option pairing steam engines with covered, enclosed carriages. Guests ride in comfort whatever the weather does overhead.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a9/Steam_Trains_with_Covered_Cars_RCT2_Icon.png/revision/latest?cb=20150628195116"},{"name":"Burger Bar","rarity":"legendary","id":"burger-bar","subtitle":"Shop & Stall","details":"Serves juicy burgers that hungry guests demolish between rides. A true park staple, it turns an empty stomach into a happy guest fast.","image":"https://vignette.wikia.nocookie.net/rct/images/9/9d/Burger_Bar_RCT2_Icon.png/revision/latest?cb=20141122111709"},{"name":"Chip Shop","rarity":"epic","id":"chip-shop","subtitle":"Shop & Stall","details":"Golden chips served hot and salty, just the way park guests love them. Simple, filling and perfect fuel for another lap of the coasters.","image":"https://vignette.wikia.nocookie.net/rct/images/8/88/Chip_Shop_RCT2_Icon.png/revision/latest?cb=20150705155055"},{"name":"Drinks Stall","rarity":"epic","id":"drinks-stall","subtitle":"Shop & Stall","details":"Ice-cold drinks for thirsty guests on hot park days. Keep one near long queues and watch parched visitors perk up and keep on riding.","image":"https://vignette.wikia.nocookie.net/rct/images/9/9f/Drinks_Stall_RCT2_Icon.png/revision/latest?cb=20141122113227"},{"name":"Information Kiosk","rarity":"epic","id":"information-kiosk","subtitle":"Shop & Stall","details":"Sells park maps and umbrellas, and points lost guests back to the fun. A small stall that saves a lot of wandering and boosts park value.","image":"https://vignette.wikia.nocookie.net/rct/images/0/00/Information_Kiosk_RCT2_Icon.png/revision/latest?cb=20150530213651"},{"name":"Pizza Stall","rarity":"epic","id":"pizza-stall","subtitle":"Shop & Stall","details":"Hot, cheesy pizza slices that hungry guests can eat on the move. A crowd-pleasing classic that keeps energy up between the big rides.","image":"https://vignette.wikia.nocookie.net/rct/images/b/be/Pizza_Stall_RCT2_Icon.png/revision/latest?cb=20150530214137"},{"name":"Toilets","rarity":"epic","id":"toilets","subtitle":"Shop & Stall","details":"The legendary RCT toilets every guest eventually needs, and needs badly. Place them everywhere, because a park without loos is pure chaos.","image":"https://vignette.wikia.nocookie.net/rct/images/6/67/Toilets_RCT2_Icon.png/revision/latest?cb=20150705161659"},{"name":"Balloon Stall","rarity":"rare","id":"balloon-stall","subtitle":"Shop & Stall","details":"Sells bright balloons that bob happily above the crowds all day long. Guests love carrying one, and a lost balloon is a very sad sight.","image":"https://vignette.wikia.nocookie.net/rct/images/2/27/Balloon_Stall_RCT2_Icon.png/revision/latest?cb=20141122111312"},{"name":"Candyfloss Stall","rarity":"rare","id":"candyfloss-stall","subtitle":"Shop & Stall","details":"Spins fluffy pink candyfloss that guests nibble as they wander the paths. Sweet, sticky and pure fairground nostalgia in every bite.","image":"https://vignette.wikia.nocookie.net/rct/images/3/35/Candyfloss_Stall_RCT2_Icon.png/revision/latest?cb=20141122112517"},{"name":"Cash Machine","rarity":"rare","id":"cash-machine","subtitle":"Shop & Stall","details":"Lets guests top up their cash without leaving the park, so the spending never has to stop. Quietly one of the smartest stalls you can build.","image":"https://vignette.wikia.nocookie.net/rct/images/d/db/Cash_Machine_RCT2_Icon.png/revision/latest?cb=20141122111931"},{"name":"Fruity Ices Stall","rarity":"rare","id":"fruity-ices-stall","subtitle":"Shop & Stall","details":"Sells refreshing fruity ices that cool down overheated guests in a hurry. A lifesaver on scorching days when the paths offer little shade.","image":"https://vignette.wikia.nocookie.net/rct/images/d/d8/Fruity_Ices_Stall_RCT2_Icon.png/revision/latest?cb=20150530213513"},{"name":"Hot Dog Stall","rarity":"rare","id":"hot-dog-stall","subtitle":"Shop & Stall","details":"Classic hot dogs with all the trimmings, served fast for guests on the go. An easy, filling snack that never goes out of style in a park.","image":"https://vignette.wikia.nocookie.net/rct/images/e/e9/Hot_Dog_Stall_RCT2_Icon.png/revision/latest?cb=20150530220315"},{"name":"Popcorn Stall","rarity":"rare","id":"popcorn-stall","subtitle":"Shop & Stall","details":"Buttery popcorn guests can carry and munch while they watch the rides go by. The smell alone draws a crowd from halfway across the park.","image":"https://vignette.wikia.nocookie.net/rct/images/e/ec/Popcorn_Stall_RCT2_Icon.png/revision/latest?cb=20150530214320"},{"name":"Souvenir Stall","rarity":"rare","id":"souvenir-stall","subtitle":"Shop & Stall","details":"Sells cuddly toys and park mementos guests take home to remember their day. A happy visitor with a souvenir is a visitor who comes back.","image":"https://vignette.wikia.nocookie.net/rct/images/1/16/Souvenir_Stall_RCT2_Icon.png/revision/latest?cb=20150530214624"},{"name":"Coffee Shop","rarity":"uncommon","id":"coffee-shop","subtitle":"Shop & Stall","details":"Serves proper coffee for guests who need a pick-me-up after too many thrill rides. A calm little pause in a busy, noisy park day.","image":"https://vignette.wikia.nocookie.net/rct/images/b/b3/Coffee_Shop_RCT2_Icon.png/revision/latest?cb=20141122112259"},{"name":"Cookie Shop","rarity":"uncommon","id":"cookie-shop","subtitle":"Shop & Stall","details":"Fresh-baked cookies, warm and sweet, that guests snap up as a treat between rides. Small enough for one hand, gone in about three bites.","image":"https://vignette.wikia.nocookie.net/rct/images/6/64/Cookie_Shop_RCT2_Icon.png/revision/latest?cb=20141122112417"},{"name":"Doughnut Shop","rarity":"uncommon","id":"doughnut-shop","subtitle":"Shop & Stall","details":"Soft, sugary doughnuts that make a perfect mid-afternoon reward for hungry guests. Hard to walk past without stopping for just one.","image":"https://vignette.wikia.nocookie.net/rct/images/f/ff/Doughnut_Shop_RCT2_Icon.png/revision/latest?cb=20141122113149"},{"name":"First Aid Room","rarity":"uncommon","id":"first-aid-room","subtitle":"Shop & Stall","details":"Patching up guests who overdid the thrill rides and feel worse for wear. A quiet room, a kind helper, and they are soon back enjoying the park.","image":"https://vignette.wikia.nocookie.net/rct/images/5/5a/First_Aid_Room_RCT2_Icon.png/revision/latest?cb=20150601221904"},{"name":"Funnel Cake Shop","rarity":"uncommon","id":"funnel-cake-shop","subtitle":"Shop & Stall","details":"Golden funnel cakes dusted with sugar, fried fresh and eaten warm. A fairground favourite that sweet-toothed guests hunt down by smell.","image":"https://vignette.wikia.nocookie.net/rct/images/2/23/Funnel_Cake_Shop_RCT2_Icon.png/revision/latest?cb=20150601222359"},{"name":"Hat Stall","rarity":"uncommon","id":"hat-stall","subtitle":"Shop & Stall","details":"Sells cheerful hats guests wear proudly for the rest of their visit. Practical in the sun and a fun little keepsake to take home afterwards.","image":"https://vignette.wikia.nocookie.net/rct/images/d/db/Hat_Stall_RCT2_Icon.png/revision/latest?cb=20150530220143"},{"name":"Ice Cream Cone Stall","rarity":"uncommon","id":"ice-cream-cone-stall","subtitle":"Shop & Stall","details":"Serves swirled ice cream cones that melt almost as fast as guests can lick them. The essential treat for a hot day packed with rides.","image":"https://vignette.wikia.nocookie.net/rct/images/3/36/Ice_Cream_Cone_Stall_RCT2_Icon.png/revision/latest?cb=20150601222749"},{"name":"Lemonade Stall","rarity":"uncommon","id":"lemonade-stall","subtitle":"Shop & Stall","details":"Sharp, sweet lemonade that quenches a thirst built up in long ride queues. Simple, cold and exactly what a hot, tired guest is craving.","image":"https://vignette.wikia.nocookie.net/rct/images/8/84/Lemonade_Stall_RCT2_Icon.png/revision/latest?cb=20150530221617"},{"name":"Pretzel Stall","rarity":"uncommon","id":"pretzel-stall","subtitle":"Shop & Stall","details":"Warm, salty pretzels twisted fresh and perfect for snacking on the move. A satisfying bite that keeps hungry guests going until lunch.","image":"https://vignette.wikia.nocookie.net/rct/images/6/6b/Pretzel_Stall_RCT2_Icon.png/revision/latest?cb=20150705161255"},{"name":"Sub Sandwich Stall","rarity":"uncommon","id":"sub-sandwich-stall","subtitle":"Shop & Stall","details":"Stacked sub sandwiches packed with filling for guests who need a real meal. Hearty, handy and far more sustaining than a quick snack.","image":"https://vignette.wikia.nocookie.net/rct/images/9/93/Sub_Sandwich_Stall_RCT2_Icon.png/revision/latest?cb=20150705160421"},{"name":"Sunglasses Stall","rarity":"uncommon","id":"sunglasses-stall","subtitle":"Shop & Stall","details":"Sells sunglasses for guests caught out by a bright, sunny park day. A small purchase that saves a lot of squinting at the coaster photos.","image":"https://vignette.wikia.nocookie.net/rct/images/c/c8/Sunglasses_Stall_RCT2_Icon.png/revision/latest?cb=20150705160123"},{"name":"Beef Noodles Stall","rarity":"common","id":"beef-noodles-stall","subtitle":"Shop & Stall","details":"Steaming bowls of beef noodles, rich and savoury, for guests wanting something warming. A hearty taste of the world menu in the middle of the park.","image":"https://vignette.wikia.nocookie.net/rct/images/5/5f/Beef_Noodles_Stall_RCT2_Icon.png/revision/latest?cb=20141122111509"},{"name":"Chicken Nuggets Stall","rarity":"common","id":"chicken-nuggets-stall","subtitle":"Shop & Stall","details":"Crispy chicken nuggets, golden and dunkable, that guests of all ages happily share. An easy crowd-pleaser when hunger strikes mid-visit.","image":"https://vignette.wikia.nocookie.net/rct/images/4/41/Chicken_Nuggets_Stall_RCT2_Icon.png/revision/latest?cb=20141122112204"},{"name":"Chips Stall","rarity":"common","id":"chips-stall","subtitle":"Shop & Stall","details":"Hot chips served crisp and golden, ready to be eaten straight from the tray. A simple, salty snack guests reach for again and again.","image":"https://vignette.wikia.nocookie.net/rct/images/9/93/Chips_Stall_RCT2_Icon.png/revision/latest?cb=20150601223450"},{"name":"Fried Chicken Stall","rarity":"common","id":"fried-chicken-stall","subtitle":"Shop & Stall","details":"Crunchy fried chicken with a proper bite, served hot for very hungry guests. Filling, flavourful and a welcome change from burgers.","image":"https://vignette.wikia.nocookie.net/rct/images/0/05/Fried_Chicken_Stall_RCT2_Icon.png/revision/latest?cb=20150530221348"},{"name":"Fried Rice Noodles Stall","rarity":"common","id":"fried-rice-noodles-stall","subtitle":"Shop & Stall","details":"Wok-tossed fried rice noodles, savoury and satisfying, served steaming hot. A delicious world-menu stop that keeps guests happily fed.","image":"https://vignette.wikia.nocookie.net/rct/images/e/e1/Fried_Rice_Noodles_Stall_RCT2_Icon.png/revision/latest?cb=20150601222234"},{"name":"Hot Chocolate Stall","rarity":"common","id":"hot-chocolate-stall","subtitle":"Shop & Stall","details":"Rich hot chocolate that warms cold hands and cheers up guests on chilly days. Especially welcome when the rain clouds roll over the park.","image":"https://vignette.wikia.nocookie.net/rct/images/6/6c/Hot_Chocolate_Stall_RCT2_Icon.png/revision/latest?cb=20150705155212"},{"name":"Iced Tea Stall","rarity":"common","id":"iced-tea-stall","subtitle":"Shop & Stall","details":"Chilled iced tea, light and refreshing, for guests who want a cooler kind of break. Perfect sipping while watching the coasters thunder past.","image":"https://vignette.wikia.nocookie.net/rct/images/f/ff/Iced_Tea_Stall_RCT2_Icon.png/revision/latest?cb=20150601222953"},{"name":"Meatball Soup Stall","rarity":"common","id":"meatball-soup-stall","subtitle":"Shop & Stall","details":"Hearty meatball soup, warm and comforting, ladled out for guests needing a proper pause. A cosy bowl that restores energy for more rides.","image":"https://vignette.wikia.nocookie.net/rct/images/3/30/Meatball_Soup_Stall_RCT2_Icon.png/revision/latest?cb=20150705160747"},{"name":"Roast Sausage Stall","rarity":"common","id":"roast-sausage-stall","subtitle":"Shop & Stall","details":"Sizzling roast sausages with a smoky snap, served hot off the stall. A hearty park classic that hungry guests can smell from the queue.","image":"https://vignette.wikia.nocookie.net/rct/images/a/a7/Roast_Sausage_Stall_RCT2_Icon.png/revision/latest?cb=20150705161714"},{"name":"Sea Food Stall","rarity":"common","id":"sea-food-stall","subtitle":"Shop & Stall","details":"Fresh-tasting seafood snacks for guests fancying something a little different by the water rides. Light, tasty and very park-by-the-sea.","image":"https://vignette.wikia.nocookie.net/rct/images/0/0f/Sea_Food_Stall_RCT2_Icon.png/revision/latest?cb=20150530215553"},{"name":"Soybean Milk Stall","rarity":"common","id":"soybean-milk-stall","subtitle":"Shop & Stall","details":"Smooth, gently sweet soybean milk, a refreshing drink with a wholesome feel. A lovely alternative for thirsty guests skipping fizzy drinks.","image":"https://vignette.wikia.nocookie.net/rct/images/e/ea/Soybean_Milk_Stall_RCT2_Icon.png/revision/latest?cb=20150705161728"},{"name":"Star Fruit Drink Stall","rarity":"common","id":"star-fruit-drink-stall","subtitle":"Shop & Stall","details":"Bright star fruit drink, tangy and tropical, that stands out on a hot park day. A refreshing sip that curious guests love to try once.","image":"https://vignette.wikia.nocookie.net/rct/images/6/6f/Star_Fruit_Drink_Stall_RCT2_Icon.png/revision/latest?cb=20150705161735"},{"name":"Sujeonggwa Stall","rarity":"common","id":"sujeonggwa-stall","subtitle":"Shop & Stall","details":"Serves sujeonggwa, a sweet Korean cinnamon punch with a warm, spiced glow. A fragrant, refreshing drink unlike anything else in the park.","image":"https://vignette.wikia.nocookie.net/rct/images/8/80/Sujeonggwa_Stall_RCT2_Icon.png/revision/latest?cb=20150705161930"},{"name":"T-Shirt Stall","rarity":"common","id":"t-shirt-stall","subtitle":"Shop & Stall","details":"Sells park T-shirts guests wear with pride long after they head home. The walking souvenir that reminds everyone what a great day it was.","image":"https://vignette.wikia.nocookie.net/rct/images/4/43/T-Shirt_Stall_RCT2_Icon.png/revision/latest?cb=20150530221850"},{"name":"Toffee Apple Stall","rarity":"common","id":"toffee-apple-stall","subtitle":"Shop & Stall","details":"Glossy toffee apples on sticks, crunchy and sweet with a sticky shine. A classic fairground treat that guests love to carry and crunch.","image":"https://vignette.wikia.nocookie.net/rct/images/f/f6/Toffee_Apple_Stall_RCT2_Icon.png/revision/latest?cb=20150530215020"},{"name":"Wonton Soup Stall","rarity":"common","id":"wonton-soup-stall","subtitle":"Shop & Stall","details":"Delicate wonton soup, light and savoury, with little dumplings in a clear, warming broth. A gentle, tasty pause between all the thrills.","image":"https://vignette.wikia.nocookie.net/rct/images/5/5d/Wonton_Soup_Stall_RCT2_Icon.png/revision/latest?cb=20150705160113"}]});
